<span class="line"><span style="color:#E1E4E8;">    &lt;</span><span style="color:#85E89D;">spring-boot.version</span><span style="color:#E1E4E8;">&gt;3.1.5&lt;/</span><span style="color:#85E89D;">spring-boot.version</span><span style="color:#E1E4E8;">&gt;</span></span>
