<span class="line"><span style="color:#E1E4E8;">        inventoryFeignClient.</span><span style="color:#B392F0;">deduct</span><span style="color:#E1E4E8;">(order.</span><span style="color:#B392F0;">getProductId</span><span style="color:#E1E4E8;">(), order.</span><span style="color:#B392F0;">getQuantity</span><span style="color:#E1E4E8;">());</span></span>
